import csv
import json
import os
from pathlib import Path

path = Path(os.environ["CONSUMER_FLOW_DIR"]) / "20190812_consumer.csv"
rows = []
with path.open("r", encoding="utf-8-sig", newline="") as f:
    for row in csv.DictReader(f):
        if row["用户"] == "贵州管网":
            rows.append(row)

result = {
    "user": "贵州管网",
    "total_consumption": round(sum(float(r["消耗量"]) for r in rows), 3),
    "distinct_supply_point_count": len({r["供气点"] for r in rows}),
    "supply_points_by_consumption_desc": [
        {"name": r["供气点"], "consumption": float(r["消耗量"])}
        for r in sorted(rows, key=lambda x: float(x["消耗量"]), reverse=True)
    ],
}
print(json.dumps(result, ensure_ascii=False))

